package dev.veltraph.client.inventory.abiphone;

import dev.veltraph.client.config.*;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class AbiphoneCallTest {
    static final AbiphoneCall.Item PHONE=new AbiphoneCall.Item("minecraft:paper","Private Phone",1,"[full-phone-components]"),CONTACT=new AbiphoneCall.Item("minecraft:paper","Builder",1,"[contact]"),MARKER=new AbiphoneCall.Item("minecraft:emerald","Builder dialogue",1,"[marker]");
    static AbiphoneCall.Request request(boolean retain){return new AbiphoneCall.Request(PHONE,"Private Contacts",CONTACT,"Builder menu",MARKER,"[Private call] Builder answered",List.of("[Private call] Builder unavailable"),1,20,retain);}
    static class Port implements AbiphoneCall.Port {
        Object player=new Object(),world=new Object(),menu;String title="";int revision,selected=2,uses,clicks,swaps,closes;boolean cursor=true,prediction,correction=true,refuse,stale,ack=true;List<AbiphoneCall.Item> inventory=new ArrayList<>(Collections.nCopies(36,AbiphoneCall.Item.EMPTY));List<AbiphoneCall.Row> rows=List.of();
        Port(){inventory.set(2,new AbiphoneCall.Item("minecraft:diamond_sword","Tool",1,"[tool]"));inventory.set(17,PHONE);}
        public AbiphoneCall.Observation read(){return new AbiphoneCall.Observation(player,world,menu,title,revision,inventory,rows,selected,cursor,prediction,correction,correction&&ack);}
        public boolean swap(AbiphoneCall.Observation o,int a,int b){if(refuse||stale)return false;swaps++;Collections.swap(inventory,a,b);correction=false;return true;}
        public boolean select(AbiphoneCall.Observation o,int slot){if(refuse)return false;selected=slot;return true;}
        public boolean use(AbiphoneCall.Observation o){if(refuse)return false;uses++;return true;}
        public boolean click(AbiphoneCall.Observation o,int slot){if(refuse||stale)return false;clicks++;return true;}
        public boolean close(AbiphoneCall.Observation o){if(refuse)return false;closes++;menu=null;title="";rows=List.of();return true;}
        void contacts(AbiphoneCall.Item item){menu=new Object();title="Private Contacts";rows=List.of(new AbiphoneCall.Row(13,false,false,item));revision++;}
        void dialogue(){menu=new Object();title="Builder menu";rows=List.of(new AbiphoneCall.Row(13,false,false,MARKER));revision++;}
    }
    private void until(AbiphoneCall c,Port p,AbiphoneCall.State state){for(int i=1;i<30&&c.state()!=state&&c.active();i++){p.correction=true;c.tick(i);}assertEquals(state,c.state(),c.reason());}
    private void choose(AbiphoneCall c,Port p){c.start(request(false),0);until(c,p,AbiphoneCall.State.WAIT_CONTACTS);p.contacts(CONTACT);c.tick(4);c.tick(5);assertEquals(AbiphoneCall.State.WAIT_RESPONSE,c.state(),c.reason());}
    @Test void receiptAndActualDialogueBothRequiredThenExactRestoration(){var p=new Port();var original=List.copyOf(p.inventory);var c=new AbiphoneCall(p);choose(c,p);c.onServerMessage(request(false).receivedReceipt());c.tick(6);assertEquals(AbiphoneCall.State.WAIT_RESPONSE,c.state());p.dialogue();until(c,p,AbiphoneCall.State.COMPLETE);assertEquals(original,p.inventory);assertEquals(2,p.selected);assertEquals(1,p.uses);assertEquals(1,p.clicks);assertEquals(2,p.swaps);assertNull(p.menu);}
    @Test void dialogueBeforeReceiptIsNotSuccess(){var p=new Port();var c=new AbiphoneCall(p);choose(c,p);p.dialogue();c.tick(6);assertEquals(AbiphoneCall.State.WAIT_RESPONSE,c.state());c.onServerMessage("[Private call] George answered");c.tick(7);assertEquals(AbiphoneCall.State.WAIT_RESPONSE,c.state());c.onServerMessage(request(false).receivedReceipt());until(c,p,AbiphoneCall.State.COMPLETE);}
    @Test void exactHandoffKeepsDialogueAfterRestoringPhone(){var p=new Port();var c=new AbiphoneCall(p);c.start(request(true),0);until(c,p,AbiphoneCall.State.WAIT_CONTACTS);p.contacts(CONTACT);c.tick(4);c.tick(5);c.onServerMessage(request(true).receivedReceipt());p.dialogue();until(c,p,AbiphoneCall.State.HANDOFF);assertTrue(c.handoffValid());assertEquals(PHONE,p.inventory.get(17));assertTrue(p.inventory.get(0).empty());assertEquals(0,p.closes);Object owned=p.menu;p.menu=new Object();assertFalse(c.handoffValid());assertFalse(c.releaseHandoff());assertEquals(0,p.closes);p.menu=owned;assertTrue(c.releaseHandoff());assertNull(p.menu);}
    @Test void missingReceiptTimesOutOnceAndRestores(){var p=new Port();var c=new AbiphoneCall(p);choose(c,p);p.dialogue();until(c,p,AbiphoneCall.State.FAILED);assertEquals(1,p.uses);assertEquals(1,p.clicks);assertEquals(PHONE,p.inventory.get(17));}
    @Test void wrongContactFullComponentsRefusedWithoutClick(){var p=new Port();var c=new AbiphoneCall(p);c.start(request(false),0);until(c,p,AbiphoneCall.State.WAIT_CONTACTS);p.contacts(new AbiphoneCall.Item(CONTACT.registryId(),CONTACT.name(),1,"[wrong metadata]"));until(c,p,AbiphoneCall.State.FAILED);assertEquals(0,p.clicks);assertEquals(PHONE,p.inventory.get(17));}
    @Test void lockedOrDuplicateContactRefused(){for(boolean locked:new boolean[]{true,false}){var p=new Port();var c=new AbiphoneCall(p);c.start(request(false),0);until(c,p,AbiphoneCall.State.WAIT_CONTACTS);p.contacts(CONTACT);p.rows=locked?List.of(new AbiphoneCall.Row(13,false,true,CONTACT)):List.of(new AbiphoneCall.Row(13,false,false,CONTACT),new AbiphoneCall.Row(14,false,false,CONTACT));until(c,p,AbiphoneCall.State.FAILED);assertEquals(0,p.clicks);}}
    @Test void duplicatePhoneAndOccupiedHotbarNeverDisplaceTools(){for(boolean duplicate:new boolean[]{true,false}){var p=new Port();if(duplicate)p.inventory.set(18,PHONE);else for(int i=0;i<9;i++)p.inventory.set(i,new AbiphoneCall.Item("minecraft:diamond_sword","Tool "+i,1,"[tool]"));var before=List.copyOf(p.inventory);var c=new AbiphoneCall(p);c.start(request(false),0);assertEquals(AbiphoneCall.State.FAILED,c.state());assertEquals(before,p.inventory);assertEquals(0,p.swaps);}}
    @Test void cancelPendingUseDrainsOwnedMenuThenRestoresWithoutContact(){var p=new Port();var c=new AbiphoneCall(p);c.start(request(false),0);until(c,p,AbiphoneCall.State.WAIT_CONTACTS);c.cancel();p.contacts(CONTACT);until(c,p,AbiphoneCall.State.CANCELLED);assertEquals(0,p.clicks);assertEquals(PHONE,p.inventory.get(17));}
    @Test void cancellationNeverRepeatsPendingContactRequest(){var p=new Port();var c=new AbiphoneCall(p);choose(c,p);c.cancel();c.cancel();p.dialogue();until(c,p,AbiphoneCall.State.CANCELLED);assertEquals(1,p.clicks);assertEquals(1,p.uses);}
    @Test void worldCursorAndOriginChangesPreserveCustody(){for(int failure=0;failure<3;failure++){var p=new Port();var c=new AbiphoneCall(p);choose(c,p);if(failure==0)p.world=new Object();if(failure==1)p.cursor=false;if(failure==2)p.inventory.set(17,new AbiphoneCall.Item("minecraft:diamond","Foreign",1,"[foreign]"));c.tick(6);assertEquals(AbiphoneCall.State.RECOVERY_REQUIRED,c.state());assertEquals(1,p.swaps);assertEquals(0,p.closes);}}
    @Test void replacementMenuIsNeverClosedOrSwapped(){var p=new Port();var c=new AbiphoneCall(p);choose(c,p);p.menu=new Object();p.title="Foreign chest";c.tick(6);c.tick(40);assertEquals(AbiphoneCall.State.RECOVERY_REQUIRED,c.state());assertEquals(0,p.closes);assertEquals(1,p.swaps);assertEquals(PHONE,p.inventory.get(0));}
    @Test void hotbarPhoneDoesNotMoveAndEarlyMessagesDoNotAcknowledge(){var p=new Port();p.inventory.set(0,PHONE);p.inventory.set(17,AbiphoneCall.Item.EMPTY);var c=new AbiphoneCall(p);c.start(request(false),0);c.onServerMessage(request(false).receivedReceipt());c.tick(1);p.contacts(CONTACT);c.tick(2);c.tick(3);p.dialogue();c.tick(4);assertEquals(AbiphoneCall.State.WAIT_RESPONSE,c.state());c.onServerMessage(request(false).receivedReceipt());until(c,p,AbiphoneCall.State.COMPLETE);assertEquals(0,p.swaps);assertEquals(PHONE,p.inventory.get(0));assertEquals(2,p.selected);}
    @Test void staleMutationBindingRefusalDoesNotRetry(){var p=new Port();var c=new AbiphoneCall(p);c.start(request(false),0);until(c,p,AbiphoneCall.State.WAIT_CONTACTS);p.contacts(CONTACT);c.tick(4);p.stale=true;c.tick(5);assertEquals(0,p.clicks);p.stale=false;until(c,p,AbiphoneCall.State.FAILED);assertEquals(0,p.clicks);}
    @Test void explicitBlankConfigurationRejectsAndIdentityIsNotTruncated(){var config=new MapConfigService();assertThrows(IllegalArgumentException.class,()->AbiphoneConfig.request(config));String longText="["+"quotes\" unicode ★ ".repeat(2000)+"]";var phone=new AbiphoneCall.Item("minecraft:paper","Phone",1,longText);var request=new AbiphoneCall.Request(phone,"Contacts",CONTACT,"NPC",MARKER,"Receipt",List.of(),1,40,false);assertEquals(longText,request.phone().components());assertThrows(IllegalArgumentException.class,()->new AbiphoneCall.Request(phone,"Contacts",CONTACT,"Contacts",MARKER,"Receipt",List.of(),1,40,false));}
    @Test void silentPredictedRestorationCannotComplete(){var p=new Port();var c=new AbiphoneCall(p);choose(c,p);p.dialogue();c.onServerMessage(request(false).receivedReceipt());p.ack=false;until(c,p,AbiphoneCall.State.RECOVERY_REQUIRED);assertEquals(PHONE,p.inventory.get(17));assertEquals(2,p.swaps);assertEquals(0,p.closes);}
    @Test void consumedHandoffReleasesAfterCallerInventoryChange(){var p=new Port();var c=new AbiphoneCall(p);c.start(request(true),0);until(c,p,AbiphoneCall.State.WAIT_CONTACTS);p.contacts(CONTACT);c.tick(4);c.tick(5);p.dialogue();c.onServerMessage(request(true).receivedReceipt());until(c,p,AbiphoneCall.State.HANDOFF);p.inventory.set(20,new AbiphoneCall.Item("minecraft:wheat","Bought Wheat",4,"[caller delta]"));assertFalse(c.handoffValid());assertTrue(c.releaseHandoff());assertEquals(PHONE,p.inventory.get(17));}
    @Test void manualRecoveryRequiresClosedMenuExactPhonePairAndSelection(){var p=new Port();var c=new AbiphoneCall(p);choose(c,p);p.cursor=false;c.tick(6);assertEquals(AbiphoneCall.State.RECOVERY_REQUIRED,c.state());assertThrows(IllegalStateException.class,()->c.start(request(false),7));assertFalse(c.acknowledgeManualRecovery());p.cursor=true;p.menu=null;p.title="";Collections.swap(p.inventory,17,0);assertFalse(c.acknowledgeManualRecovery());p.selected=2;assertTrue(c.acknowledgeManualRecovery());assertEquals(AbiphoneCall.State.FAILED,c.state());assertEquals(1,p.uses);assertEquals(1,p.clicks);assertEquals(1,p.swaps);}
}
